\label{lem:A-prop}
Let $f \in \Delta_m({\mathcal T})$. The operators $A_f^k$ satisfy
\begin{itemize}
\item[i)] $A_f^k (\Lambda^k({\mathcal T}_f)) \subset \Lambda^k({\mathcal S}_f^c)$,
\item[ii)]  $A_f^k ({\mathcal P}_r\Lambda^k({\mathcal T}_f) ) \subset {\mathcal P}_r\Lambda^k({\mathcal S}_f^c)$ and
$A_f^k ({\mathcal P}_r^-\Lambda^k({\mathcal T}_f) ) \subset {\mathcal P}_r^-\Lambda^k({\mathcal S}_f^c)$,
\item[iii)] $\operatorname{tr}_{f} L_f^*A_f^k u = \operatorname{tr}_f u$ for $u \in \Lambda^k({\mathcal T}_f)$, $k \le m \le n$.
\end{itemize}

\label{lem:commute-C1}
  Assume that for each $f \in \Delta({\mathcal T})$ and $e \in \Delta_1(f)$, we can
  construct operators $R_{e,f}^1$ such that relation \eqref{R1d-delta}
  holds. Define the operator $C_m^1$ by
 \begin{equation*}

 C_m^1 u = \sum_{\substack {f \in \Delta_{m+j}({\mathcal T})\\ 0 \le j \le 1}} C_{m,f}^1 u,
 \end{equation*}
 where $C_{m,f}^1$ is given by \eqref{Cmf-k} if $f \in \Delta_m({\mathcal T})$, and by 
 \begin{equation*}
 C_{m,f}^1u =  \sum_{e \in \Delta_1(f)} \sum_{g \in \bar \Delta(f \cap e^*)}
 (-1)^{|f| - |g|}\frac{\phi_{e}}{\rho_g^2}
 L_{g}^*R_{e,f}^1 u
 \end{equation*}
 if $f \in \Delta_{m+1}({\mathcal T})$. Then the commuting relation 
 $dC_m^0 u =
 C_m^{1}du$ holds.

\label{lem:delta-prop}
The operators $\delta$ and $\delta^+$ satisfy
\[
\delta \circ \delta = 0, \quad \delta^+ \circ \delta^+ = 0, \quad \text{and } 
\delta \circ \delta^+ = - \delta^+ \circ \delta.
\]

The support property follows from the support property
  of the functions $w_{e,f}$, while $\delta^+z = 0$ follows from the
  complex property of the operator $\delta^+$.  Finally, for $e \in
  \Delta_j(f)$, we have
\begin{multline*}
dz_{e,f} = d(\delta^+w)_{e,f} = (\delta^+ dw)_{e,f} = (-1)^{j} ((\delta^+ \circ \delta) w)_{e,f} 
\\
= (-1)^{j+1} ((\delta \circ \delta^+) w)_{e,f}
= (-1)^{j+1} (\delta z)_{e,f},
\end{multline*}
and this completes the proof.

\label{prop:R-relation}
  The operators $R_{e,f}^k$ satisfy the two identities
  \eqref{Rkd-delta} and \eqref{Rk-delta+}.

For any $e \in \Delta_j(f)$, we have 
 \[
 (\delta^+ R^ku)_{e,f} =  \operatorname{tr}_{{\mathcal S}_{f \cap e^*}^c}\int_{\Omega}
 (\Pi_{j-1} G^*u) \wedge (\delta^+ z)_{e,f},
 \]













 and the relation \eqref{Rk-delta+} follows directly from the second
 identity of \eqref{z-prop}.  To show \eqref{Rkd-delta}, we use the
 first relation of \eqref{z-prop}, \eqref{rep-delta-R}, and
 integration by parts to obtain
\begin{multline*}
-(\delta R^{k} u)_{e,f }
= (-1)^{j} \int_{\Omega} \Pi_{j-1} G^* u \wedge d_{\Omega }z_{e,f}
\\
= \int_{\Omega} d_{\Omega }\Pi_{j -1}G^* u \wedge z_{e,f}
= \int_{\Omega} \Big[(-1)^{j+1} d_{{\mathcal S} }\Pi_{j}G^* u 
+ \Pi_jG^*du\Big] \wedge z_{e,f},
\end{multline*}
where we have used \eqref{dG*} to obtain the last equality. However, since
\begin{equation*}

d R_{e,f}^k u = \int_{\Omega} d_S \Pi_j G^* u \wedge z_{e,f},
\end{equation*}
we see that the right hand side above is exactly equal to
\[
(-1)^{j+1} dR_{e,f}^k u + R_{e,f}^{k+1} du ,
\]
and hence the desired result is obtained.

\label{lem:Qrewrite}
If $u \in \Lambda^k({\mathcal T})$ and $g \in \Delta_s(T)$, then
\begin{equation}
\label{Cmgk-ident}
C_m^k(g,T)u - \frac{n-m}{n-s} 
\sum_{\substack{f \in \Delta_m(T) \\ f \supset g}} L_g^* A_{f}^k u
= d Q_m^k u + Q_{m}^{k+1} du,
\end{equation}
where the operators $Q_m^k = Q_m^k(g,T)$ are given by
\begin{equation*}
Q_m^k u = \frac{1}{n-s}
\sum_{j = 1}^k (-1)^{j }(j-1)! \sum_{\substack{f \in \Delta_{m+j}(T)\\ f \supset g}} 
\sum_{e \in \Delta_j(f \cap g^*)} (\delta \phi)_{e}
\wedge L_g^* b^{-j}R_{e,f}^k u,
\end{equation*}
with
$(\delta \phi)_e = \sum_{i \in I(e)} (-1)^{\sigma(x_i)} \phi_{e(\hat x_i)}$.
In particular, $Q_m^0 = 0$ and the case $g =\emptyset$ corresponds to $s = -1$.

\label{lem:Qrewrite-0}
If $g \in \Delta_s(T)$, then
\[
C_{m,0}^k(g,T)u - \frac{n-m}{n-s} 
\sum_{\substack{f \in \Delta_m(T) \\ f \supset g}} L_g^* A_{f}^k u
=  \frac{1}{n-s} \sum_{(f,e) \in \Delta(m,1)}
\frac{(\delta \phi)_{e}}{\rho_g}
\wedge L_g^* (\delta R^ku)_{e,f},
\]
where the case $g =\emptyset$ corresponds to $s = -1$.

We observe 
 that the desired identity will follow if we can show that 
\begin{multline}
\label{init-id}
 \sum_{(e,f) \in \Delta(m,1)}(\delta \phi)_{e}
\wedge L_g^* (\delta R^ku)_{e,f} - 
(n-s)  \sum_{(e,f) \in \Delta(m,0)}
 \phi_e \wedge L_{g}^* R_{e,f}^ku
\\
=(m-s) \rho_g \sum_{\substack{f \in \Delta_{m}(T)\\ f \supset g}} L_g^*A_f^k u.
\end{multline}
By using the special definitions of $\phi_e$ and $R_{e,f}^k$ 
for $e \in \Delta_0$, it is straightforward to verify that 
\begin{align*}
&\sum_{\substack{f \in \Delta_{m+1}(T)\\ f \supset g}} 
\sum_{e \in \Delta_1(f \cap g^*)} (\delta \phi)_{e}
\wedge L_g^* (\delta R^ku)_{e,f}\\
& = -
\sum_{\substack{f \in \Delta_{m+1}(T)\\ f \supset g}} 
\sum_{e \in \Delta_1(f \cap g^*)} \sum_{i \in I(e)} (-1)^{\sigma_e(x_i)}\lambda_{e(\hat x_i)} 
\sum_{p \in I(e)} (-1)^{\sigma_e(x_p)}
\wedge L_g^* A_{f(\hat x_p)}^k \\
&=\sum_{\substack{f \in \Delta_{m}(T)\\ f \supset g}} 
\sum_{ \substack{p \in I(f^*)\\i \in I(f\cap g^*)}}
(\lambda_p - \lambda_i)\wedge L_g^*A_f^k u
=\sum_{\substack{f \in \Delta_{m}(T)\\ f \supset g}} 
\sum_{ \substack{p \in I(g^*)\\i \in I(f\cap g^*)}}
(\lambda_p - \lambda_i)\wedge L_g^*A_f^k u,
\end{align*}
while
\[
-(n-s) \sum_{(e,f) \in \Delta(m,0)}
 \phi_e \wedge L_{g}^* R_{e,f}^ku  
= \sum_{\substack{f \in \Delta_{m}(T)\\ f \supset g}} 
 \sum_{ \substack{p \in I(g^*)\\i \in I(f\cap g^*)}}
\lambda_i \wedge L_g^*A_f^k u.
\]













As a consequence, the left hand side of \eqref{init-id} is 
\[
 \sum_{\substack{f \in \Delta_{m}(T)\\ f \supset g}} 
\sum_{ \substack{p \in I(g^*)\\i \in I(f\cap g^*)}}
\lambda_p \wedge L_g^*A_f^k u = (m-s) \rho_g 
\sum_{\substack{f \in \Delta_{m}(T)\\ f \supset g}} L_g^*A_f^k u,
\]
and this completes the proof.

\label{lem:im-0}
The identity 
 \begin{multline}\label{im-0}
 \sum_{(e,f) \in \Delta(m,j)}
 d \Big(\frac{(\delta \phi)_{e}}{\rho_g^j}\Big) 
\wedge L_g^* R_{e,f}^k u + \frac{j}{\rho_g^{j+1}} \sum_{(e,f) \in \Delta(m,j+1)}
 (\delta \phi)_e
 \wedge L_g^* (\delta R^k u)_{e,f} 
\\
= \frac{j}{\rho_g^{j+1}} (n-s)  \sum_{(e,f) \in \Delta(m,j)} \phi_{e}  
\wedge L_g^* R_{e,f}^k u
\end{multline}
holds for any $0 \le j \le m$.

(of Lemma~\ref{lem:Qrewrite}) 
We introduce the operators 
  \[
  Q_{m,\ell}^k u  = \frac{1}{n-s}
\sum_{j = 1}^{\ell} (-1)^{j }(j-1)! \sum_{(e,f) \in \Delta(m,j)} 
(\delta \phi)_{e} \wedge L_g^* b^{-j} R_{e,f}^k u,
\]
such that $Q_{m,k}^k = Q_m^k$, and $Q_{m,0}^k = 0$.
We will now use induction with respect to $\ell$ to show that 
\begin{multline}
\label{Cmgk-ident-reduced}
C_{m,\ell}^k(g,T)u - \frac{n-m}{n-s} 
\sum_{\substack{f \in \Delta_m(T) \\ f \supset g}} L_g^* A_{f}^k u
= d Q_{m,\ell}^k u + Q_{m,\ell}^{k+1} du 
\\
+  \frac{(-1)^{\ell} \ell!}{n-s} \sum_{(e,f) \in \Delta(m,\ell +1)}
\frac{(\delta \phi)_{e}}{\rho_g^{\ell +1}}
\wedge L_g^* (\delta R^ku)_{e,f}, \quad \ell = 0, 1, \ldots k.
\end{multline}
For $\ell = 0$, this is exactly the identity given in
Lemma~\ref{lem:Qrewrite-0}.  On the other hand, for $\ell = k$, we have
that
\[
\mathcal Q_{m,k}^{k+1} du +   \frac{(-1)^k k!}{n-s} \sum_{(e,f) \in \Delta(m,k +1)}
\frac{(\delta \phi)_{e}}{\rho_g^{k +1}}
\wedge L_g^* (\delta R^ku)_{e,f} = Q_m^{k+1} du,
\]
where we have used the facts that $\rho_g = L_g^* b$ and $(\delta
R^ku)_{e,f} = - R_{e,f}^{k+1} du$ for $e \in \Delta_{k+1}(f)$, cf.
\eqref{Rkd-delta}. So the desired identity, \eqref{Cmgk-ident} ,
follows from \eqref{Cmgk-ident-reduced} with $\ell = k$.

If we assume that \eqref{Cmgk-ident-reduced} holds for $\ell -1$, then
\begin{align*}
C_{m,\ell}^k&(g,T) u - \frac{n-m}{n-s} 
\sum_{\substack{f \in \Delta_m(T) \\ f \supset g}} L_g^* A_{f}^k u
= (-1)^{\ell}\ell! \sum_{(e,f) \in \Delta(m,\ell )}
\frac{\phi_{e}}{\rho_g^{\ell+1 }}
\wedge L_g^* R_{e,f}^ku\\
&+ dQ_{m,\ell -1}^ku + Q_{m,\ell -1}^{k+1} du 
-   \frac{(-1)^{\ell} (\ell-1)!}{n-s} \sum_{(e,f) \in \Delta(m,\ell )}
\frac{(\delta \phi)_{e}}{\rho_g^{\ell }}
\wedge L_g^* (\delta R^ku)_{e,f}\\
&= dQ_{m,\ell -1}^ku + Q_{m,\ell }^{k+1} du \\
&+ \sum_{(e,f) \in \Delta(m,\ell )} \Big[(-1)^{\ell}\ell! 
\frac{\phi_{e}}{\rho_g^{\ell +1}}
\wedge L_g^* R_{e,f}^ku  
- \frac{ (\ell-1)!}{n-s} \frac{(\delta \phi)_{e}}{\rho_g^{\ell }}
\wedge dL_g^* R_{e,f}^ku \Big],
\end{align*}
where we have used \eqref{Rkd-delta} for the last equality. However, by 
\eqref{im-0}, the last sum can rewritten as 
\[
\frac{ (-1)^{\ell} (\ell-1)!}{n-s} \Big[
\sum_{(e,f) \in \Delta(m,\ell )} 
 d \Big(\frac{(\delta \phi)_{e}}{\rho_g^{\ell }}
\wedge L_g^* R_{e,f}^ku \Big) + \ell \hskip -7pt 
\sum_{(e,f) \in \Delta(m,\ell +1)}
\frac{(\delta \phi)_{e}}{\rho_g^{\ell +1}}
\wedge L_g^* (\delta R^ku)_{e,f} \Big],
\]
and hence we obtain the identity \eqref{Cmgk-ident-reduced} at level
$\ell$. This completes the induction argument, and hence the proof of
Lemma~\ref{lem:Qrewrite}.

(of Lemma~\ref{lem:im-0}) We observe that if $e \in
  \Delta_j(f \cap g^*)$, it follows from \eqref{d-phi} and the
  identity $\rho_g = \sum_{p \in I(g^*)} \lambda_p$ that
\begin{multline}\label{im-1}
d \Big(\frac{(\delta \phi)_{e}}{\rho_g^j}\Big) 
= \frac{j}{\rho_g^{j+1}} \sum_{i \in I(e)} (-1)^{\sigma_e(x_i)}
\sum_{p \in I(g^*)} \phi_{[x_p,e(\hat x_i)]}
\\
= \frac{j}{\rho_g^{j+1}} \Big[ (j+1)\phi_e 
+  \sum_{i \in I(e)} (-1)^{\sigma_e(x_i)}
\sum_{p \in I(g^*\setminus e)} \phi_{[x_p,e(\hat x_i)]} \Big].
\end{multline}
To proceed, we will treat the sum with respect to $p$ above in the two
cases $p \in I ((g^* \setminus e) \cap f)$ and $p \in I ((g^*
\setminus e) \cap f^* = I(f^*)$ separately.  In the first case, for
any fixed $f \in \Delta_{m+j}(T)$, consider
\begin{multline*}
\sum_{e \in \Delta_j(f \cap g^*)} \sum_{i \in I(e)} (-1)^{\sigma_e(x_i)}
\sum_{p \in I((g^* \setminus e)\cap f )} \phi_{[x_p,e(\hat x_i)]}\wedge L_g^* R_{e,f}^k u 
\\
= \sum_{e \in \Delta_{j+1}(f \cap g^*)} \sum_{p \in I(e)}\sum_{i \in I(e(\hat x_p))}
 (-1)^{\sigma_{e(\hat x_p)}(x_i) + \sigma_{e(\hat x_i)}(x_p)} \phi_{e(\hat x_i)} 
\wedge L_g^* R_{e(\hat x_p),f}^k u,
\end{multline*}
where the identity is obtained by introducing $e^\prime \in
\Delta_{j+1}$ as the ordered version of the simplex $[x_p,e]$,
i.e., $(-1)^{\sigma_{e^\prime}(x_p)}e^\prime = [x_p,e]$, and then
dropping primes.  However, it is easy to show that
\begin{equation}\label{sum-sigma}
\sigma_{e(\hat x_p)}(x_i) + \sigma_{e(\hat x_i)}(x_p)
= \sigma_{e}(x_i) + \sigma_{e}(x_p) -1.
\end{equation}
As a consequence, we can express the sum above as 
\begin{align*}
&\sum_{e \in \Delta_j(f \cap g^*)} \sum_{i \in I(e)} (-1)^{\sigma_e(x_i)}
\sum_{p \in I((g^* \setminus e)\cap f )} \phi_{[x_p,e(\hat x_i)]}\wedge L_g^* R_{e,f}^k u \\
&= - \sum_{e \in \Delta_{j+1}(f \cap g^*)} \sum_{p \in I(e)}
\sum_{i \in I(e)}
 (-1)^{\sigma_{e}(x_i) + \sigma_{e}(x_p)} \phi_{e(\hat x_i)} 
\wedge L_g^* R_{e(\hat x_p),f}^k u\\
 &\qquad + \sum_{e \in \Delta_{j+1}(f \cap g^*)} \sum_{p \in I(e)}
 \phi_{e(\hat x_p)} \wedge L_g^* R_{e(\hat x_p),f}^k u \\
 &=  - \sum_{e \in \Delta_{j+1}(f \cap g^*)} (\delta \phi)_e 
\wedge L_g^* (\delta^+ R^k u)_{e,f}
+ ( m-s-1 ) \sum_{e \in \Delta_{j}(f \cap g^*)} \phi_e \wedge L_g^* R_{e,f}^k u,
 \end{align*}
 where we have used the fact that for $f \in \Delta_{m+j}(T)$ and $g
\in \Delta_s(f)$, $|f \cap g^*| = m+j - s$. Choosing an 
$e \in \Delta_j(f \cap g^*)$ leaves $m+j -s - j-1 = m-s-1$ vertices
that can be deleted from an  $e^\prime \in \Delta_{j+1}(f \cap g^*)$
to produce that same $e$.

However, the first term on the right hand side vanishes since
$(\delta^+ R u)_{e,f} = 0$ by
Proposition~\ref{prop:R-relation}. Therefore, we can conclude that
 \begin{multline}\label{im-2}
 \sum_{e \in \Delta_j(f \cap g^*)} \sum_{i \in I(e)} (-1)^{\sigma_e(x_i)}
\sum_{p \in I((g^* \setminus e)\cap f )} 
\phi_{[x_p,e(\hat x_i)]}\wedge L_g^* R_{e,f}^k u
\\
= ( m-s-1 ) \sum_{e \in \Delta_{j}(f \cap g^*)} \phi_e \wedge L_g^* R_{e,f}^k u.
\end{multline}
 In an analogous manner, and by using the identity \eqref{sum-sigma} as
above, we obtain
 \begin{align*}
\sum_{(e,f) \in \Delta(m,j)}& \sum_{i \in I(e)} (-1)^{\sigma_e(x_i)}
\sum_{p \in I(f^* )} \phi_{[x_p,e(\hat x_i)]}\wedge L_g^* R_{e,f}^k u \\




 &= -\sum_{(e,f) \in \Delta(m,j+1)} \sum_{p \in I(e)}\sum_{i \in I(e)}
 (-1)^{\sigma_{e}(x_i) + \sigma_{e}(x_p)} 
 \phi_{e(\hat x_i)} 
 \wedge L_g^* R_{e(\hat x_p),f(\hat x_p)}^k u\\
 &+ \sum_{(e,f) \in \Delta(m,j+1)} \sum_{p \in I(e)}   \phi_{e(\hat x_p)} 
 \wedge L_g^* R_{e(\hat x_p),f(\hat x_p)}^k u,
 \end{align*}
 where as above 
 we have introduced $(-1)^{\sigma_{e^\prime}(x_p)} e^\prime = [x_p,e]$,
 and the corresponding extension of $f$ to $f^\prime \in
 \Delta_{m+j+1}$ by including $x_p$.  However, the final right hand
 side above can rewritten as
\[
 -\sum_{(e,f) \in \Delta(m,j+1)}
 (\delta \phi)_e
 \wedge L_g^* (\delta R^k u)_{e,f}
 + (n- m -j)\sum_{(e,f) \in \Delta(m,j)}
  \phi_{e} 
 \wedge L_g^* R_{e,f}^k u.
\]
 In this case,  for each $f \in \Delta_{m+j}(T)$, there are 
$n-m-j$ vertices that can be deleted from $f^\prime \in \Delta_{m+j+1}(T)$ 
to produce the same $f$. Deleting this same vertex from $e^{\prime}
\in \Delta_{j+1}(f^\prime \cap g^*)$ produces the above result.


By combining this result with \eqref{im-1} and \eqref{im-2}, we obtain
\begin{multline*}
  \sum_{(e,f) \in \Delta(m,j)} d \Big(\frac{(\delta \phi)_{e}}{\rho_g^j}\Big) 
\wedge L_g^* R_{e,f}^k u 
\\
=\frac{j}{\rho_g^{j+1}} \Big[ (n-s) \sum_{(e,f) \in \Delta(m,j)}
 \phi_e\wedge L_g^* R_{e,f}^k u 
-\sum_{(e,f) \in \Delta(m,j+1)} 
 (\delta \phi)_e
 \wedge L_g^* (\delta R^k u)_{e,f} \Big],
\end{multline*}
which is exactly the desired identity.

\label{lem:C-bound}
There exists a constant $c$, depending on the mesh ${\mathcal T}$ only through
the shape-regularity constant $c_{{\mathcal T}}$, such that for $f \in
\Delta_{m+j}({\mathcal T})$ and $e \in \Delta_j(f)$, we have
\begin{equation}
\label{Cmfkbound}
\|C_{m,f}^k u\|_{L^2(\Omega_f)} \le c \|u\|_{L^2(\Omega_{f}^{E})},
\end{equation}
where $0 \le m \le n$ and $0 \le j \le k$.

\label{thm:L2bound}
There exists a constant $c$, depending on the shape-regularity
constant $c_{{\mathcal T}}$, such that for $0 \le m \le n$, we have
\[
 \|B_{m}^k u\|_{L^2(\Omega)}, 
 \Big(\sum_{j=0}^k \sum_{f \in \Delta_{m+j}({\mathcal T})} 
\|B_{m,f}^k u\|_{L^2(\Omega)}^2 \Big)^{1/2} 
 \le c \|u\|_{L^2(\Omega)}.
 \]

\label{thm:Hbound}
There exists a constant
$c$, depending on the shape regularity constant $c_{{\mathcal T}}$, such that
\begin{equation*}
 \|B_{m}^k u\|_{H \Lambda(\Omega)} \le c \|u\|_{H \Lambda(\Omega)}, \quad 0 \le m \le n.
\end{equation*}

\label{lem:max-min-vertex}
There is a
  constant $c$, depending on ${\mathcal T}$ only through the shape-regularity
  constant $c_{{\mathcal T}}$, such that
\begin{equation}\label{max-min}
\max_{T \in \Delta_n({\mathcal T}_{e,f})} h_T \le
c \min_{T \in \Delta_n({\mathcal T}_{e,f})} h_T, 
\quad f \in \Delta({\mathcal T}), \, e \in \Delta(f).
\end{equation}
